module protocol::market;

use std::type_name::{Self, TypeName};
use std::string::String;

use sui::balance::Balance;
use sui::clock::Clock;
use sui::coin::{Self, Coin};
use sui::dynamic_field;
use sui::object_table::{Self, ObjectTable};

use x_oracle::x_oracle::XOracle;
use x_oracle::user_oracle::{get_price, get_price_with_check};

use math::float::{Self, Decimal};
use protocol::generic_store::{Self, GenericCoinTypeStorage};
use protocol::coin_decimals_registry::CoinDecimalsRegistry;

use protocol::asset::{Self, Asset, AssetConfig};
use protocol::error;
use protocol::interest::InterestModel;
use protocol::obligation::Obligation;
use protocol::reserve::{Self, Reserve, ReserveFlashLoan};
use protocol::value::coin_value;
use protocol::emode::{Self, EModeGroup, EModeGroupRegistry};
use protocol::adl::{new_auto_deleverage_registry, AutoDeleverageRegistry};
use protocol::liquidity_miner::{Self, LiquidityMiner};
use x_oracle::user_oracle::get_spot_price;

const DEFAULT_EMA_SPOT_DIFF_TOLERANCE_BPS: u64 = 1000; // 10%
const DEFAULT_EMA_SPOT_DIFF_DENOMINATOR: u64 = 10000;

public struct MarketConfiguration has store, copy, drop {
    close_factor: Decimal,
    close_factor_bypass_min_value: u64,
}

/// Flash loan hot potato
public struct FlashLoan<phantom MarketType, phantom CoinType> {
    inner: ReserveFlashLoan<MarketType, CoinType>,
    fee: u64,
}

public fun loan_amount<MarketType, CoinType>(self: &FlashLoan<MarketType, CoinType>): u64 {
    self.inner.amount()
}

public fun fee<MarketType, CoinType>(self: &FlashLoan<MarketType, CoinType>): u64 {
    self.fee
}

// a default emode group for lending
public(package) fun lending_default_emode_group(): u8 { 0 }

public struct Market<phantom MarketType> has key, store {
    id: UID,

    assets: GenericCoinTypeStorage<Asset<MarketType>>,
    reserves: GenericCoinTypeStorage<Reserve<MarketType>>,

    /// The max price tolerance between ema and spot price. If the difference is more than this value
    /// borrow and withdraw will be rejected, default to 10% per asset.
    ema_spot_tolerance: GenericCoinTypeStorage<Decimal>,

    emode_group_registry: EModeGroupRegistry,

    obligations: ObjectTable<ID, Obligation<MarketType>>,

    liquidity_miner: LiquidityMiner<MarketType>,

    // dynamic fields:
    // - circuit_break
    // - market_config
    // - adl_registry
}

// dynamic field keys
public struct MarketConfigurationKey has copy, drop, store {}
public struct CircuitBreakKey has copy, drop, store {}
public struct ADLRegistryKey has copy, drop, store {}

// ==================== MarketConfiguration Constructor =====================
/// Create a new market configuration
public(package) fun new_market_configuration(close_factor: Decimal, close_factor_bypass_min_value: u64): MarketConfiguration {
    MarketConfiguration { close_factor, close_factor_bypass_min_value }
}

// ==================== Constructor =====================
public(package) fun new<MarketType>(
    market_config: MarketConfiguration,
    ctx: &mut TxContext,
): Market<MarketType> {
    let mut market = Market {
        id: object::new(ctx),

        emode_group_registry: emode::new_e_mode_registry(ctx),

        assets: generic_store::new(ctx),
        reserves: generic_store::new(ctx),

        ema_spot_tolerance: generic_store::new(ctx),

        obligations: object_table::new(ctx),
        liquidity_miner: liquidity_miner::new_liquidity_miner(ctx),
    };

    dynamic_field::add(&mut market.id, MarketConfigurationKey {}, market_config);
    dynamic_field::add(&mut market.id, CircuitBreakKey {}, false);
    dynamic_field::add(&mut market.id, ADLRegistryKey {}, new_auto_deleverage_registry(ctx));

    market
}

// admin
public(package) fun emode_registry_mut<MarketType>(self: &mut Market<MarketType>): &mut EModeGroupRegistry {
    &mut self.emode_group_registry
}

public(package) fun trigger_circuit_break<MarketType>(self: &mut Market<MarketType>) {
    let is_circuit_break = dynamic_field::borrow_mut(&mut self.id, CircuitBreakKey {});

    assert!(!*is_circuit_break, error::already_under_circuit_break());
    *is_circuit_break = true;
}

public(package) fun discharge_circuit_break<MarketType>(self: &mut Market<MarketType>) {
    let is_circuit_break = dynamic_field::borrow_mut(&mut self.id, CircuitBreakKey {});

    assert!(*is_circuit_break, error::not_under_circuit_break());
    *is_circuit_break = false;
}

public(package) fun update_market_config<MarketType>(self: &mut Market<MarketType>, config: MarketConfiguration) {
    *dynamic_field::borrow_mut(&mut self.id, MarketConfigurationKey {}) = config;
}

public(package) fun adl_registry_mut<MarketType>(self: &mut Market<MarketType>): &mut AutoDeleverageRegistry {
    dynamic_field::borrow_mut<ADLRegistryKey, AutoDeleverageRegistry>(&mut self.id, ADLRegistryKey {})
}

// =============== Public Getter Functions ==============

public fun assert_emode_group_exists<MarketType>(self: &Market<MarketType>, group: u8) {
    self.emode_group_registry.ensure_group_exists(group)
}

public fun emode_registry<MarketType>(self: &Market<MarketType>): &EModeGroupRegistry {
    &self.emode_group_registry
}

public(package) fun supported_assets<MarketType>(self: &Market<MarketType>): vector<TypeName> {
    self.assets.keys()
}

public(package) fun has_circuit_break_triggered<MarketType>(self: &Market<MarketType>): bool {
    *dynamic_field::borrow(&self.id, CircuitBreakKey {})
}

public(package) fun market_config<MarketType>(self: &Market<MarketType>): &MarketConfiguration {
    dynamic_field::borrow(&self.id, MarketConfigurationKey {})
}

public(package) fun adl_registry<MarketType>(self: &Market<MarketType>): &AutoDeleverageRegistry {
    dynamic_field::borrow<ADLRegistryKey, AutoDeleverageRegistry>(&self.id, ADLRegistryKey {})
}

public(package) fun asset_by_type<MarketType>(
    self: &Market<MarketType>,
    name: TypeName,
): &Asset<MarketType> {
    self.assets.load_by_type<Asset<MarketType>>(name)
}

public(package) fun reserve_by_type<MarketType>(
    self: &Market<MarketType>,
    name: TypeName,
): &Reserve<MarketType> {
    self.reserves.load_by_type<Reserve<MarketType>>(name)
}

public fun exchange_rate<MarketType>(self: &Market<MarketType>, coin_type: TypeName): Decimal {
    self.reserve_by_type<MarketType>(coin_type).exchange_rate()
}

public fun borrow_obligation<MarketType>(
    self: &Market<MarketType>,
    obligation_id: ID,
): &Obligation<MarketType> {
    self.obligations.borrow(obligation_id)
}

// =============== Admin Functions ==============
public(package) fun market_asset_borrow_mut<MarketType, CoinType>(
    self: &mut Market<MarketType>,
): &mut Asset<MarketType> {
    self.assets.load_mut_by_type(type_name::with_defining_ids<CoinType>())
}

public(package) fun set_ema_spot_tolerance<MarketType, CoinType>(
    self: &mut Market<MarketType>,
    tolerance_bps: u64
) {
    assert!(tolerance_bps < DEFAULT_EMA_SPOT_DIFF_DENOMINATOR, error::invalid_params_error());

    let tolerance = math::float::from_quotient(tolerance_bps, DEFAULT_EMA_SPOT_DIFF_DENOMINATOR);

    let t = self.ema_spot_tolerance.load_mut_by_type(type_name::with_defining_ids<CoinType>());
    *t = tolerance;
}

/// Take revenue from market reserves
public(package) fun take_revenue<MarketType, CoinType>(
    self: &mut Market<MarketType>,
    amount: u64,
    ctx: &mut TxContext,
): Coin<CoinType> {
    let reserve = self.reserves.load_mut_by_type(type_name::with_defining_ids<CoinType>());
    let balance = reserve::take_revenue<MarketType, CoinType>(reserve, amount);
    coin::from_balance(balance, ctx)
}

// ================== Internal Update Functions ================
public(package) fun onboard_new_asset<MarketType, CoinType>(
    self: &mut Market<MarketType>,
    interest_model: InterestModel,
    borrow: AssetConfig,
    now: u64,
    ctx: &mut TxContext,
) {
    assert!(!self.assets.supports<Asset<MarketType>, CoinType>(), error::asset_already_onboarded());

    let new_asset = asset::new<MarketType>(interest_model, borrow, ctx);
    self.assets.store<Asset<MarketType>, CoinType>(new_asset);

    let reserve = reserve::new<MarketType, CoinType>(ctx, now);
    self.reserves.store<Reserve<MarketType>, CoinType>(reserve);

    self.ema_spot_tolerance.store<Decimal, CoinType>(float::from_quotient(DEFAULT_EMA_SPOT_DIFF_TOLERANCE_BPS, DEFAULT_EMA_SPOT_DIFF_DENOMINATOR));

    self.liquidity_miner.support_coin<MarketType, CoinType>(ctx);
}

public(package) fun handle_new_obligation<MarketType>(
    self: &mut Market<MarketType>,
    obligation: Obligation<MarketType>,
) {
    self.obligations.add(object::id(&obligation), obligation);
}

public(package) fun borrow_liquidity_mining<MarketType>(self: &Market<MarketType>): &LiquidityMiner<MarketType> {
    &self.liquidity_miner
}

public(package) fun borrow_liquidity_mining_mut<MarketType>(self: &mut Market<MarketType>): &mut LiquidityMiner<MarketType> {
    &mut self.liquidity_miner
}

public(package) fun handle_mint<MarketType, CoinType>(
    self: &mut Market<MarketType>,
    obligation: ID,

